package migration

import (
	"embed"
	"fmt"
	"io/fs"
	"path"
	"strings"

	"github.com/go-gormigrate/gormigrate/v2"
	"gorm.io/gorm"
)

// sqlDir holds the versioned migrations generated by Atlas (https://atlasgo.io) from the GORM
// models, see server/atlas.hcl. The files are named <version>_<name>.sql and are applied in order.
//
//go:embed sql/*.sql
var sqlDir embed.FS

// baselineVersion is the version of the Atlas baseline snapshot.
// It captures the schema created by the legacy migrations (up to 20250412000000), so
// Migrate skips it, while MigrateFromBaseline uses it to create the schema directly.
const baselineVersion = "20250412000000"

type sqlMigrationFile struct {
	name    string
	version string
	stmts   []string
}

func (f sqlMigrationFile) apply(tx *gorm.DB) error {
	for _, stmt := range f.stmts {
		if err := tx.Exec(stmt).Error; err != nil {
			return err
		}
	}
	return nil
}

// sqlMigrationFiles returns the baseline and all later SQL migrations, ordered by version
func sqlMigrationFiles() ([]sqlMigrationFile, error) {
	entries, err := fs.ReadDir(sqlDir, "sql") // sorted by filename
	if err != nil {
		return nil, err
	}
	var files []sqlMigrationFile
	for _, e := range entries {
		version, _, ok := strings.Cut(e.Name(), "_")
		if !ok || len(version) != len(baselineVersion) {
			return nil, fmt.Errorf("migration %s: expected a name like <version>_<name>.sql", e.Name())
		}
		if len(files) == 0 && version != baselineVersion {
			return nil, fmt.Errorf("migration %s: the first migration must be the baseline %s", e.Name(), baselineVersion)
		}
		content, err := sqlDir.ReadFile(path.Join("sql", e.Name()))
		if err != nil {
			return nil, err
		}
		files = append(files, sqlMigrationFile{name: e.Name(), version: version, stmts: splitStatements(string(content))})
	}
	if len(files) == 0 {
		return nil, fmt.Errorf("no sql migrations found")
	}
	return files, nil
}

// sqlMigrations returns the SQL migrations after the baseline as gormigrate migrations
func sqlMigrations() ([]*gormigrate.Migration, error) {
	files, err := sqlMigrationFiles()
	if err != nil {
		return nil, err
	}
	migrations := make([]*gormigrate.Migration, 0, len(files)-1)
	for _, f := range files[1:] {
		migrations = append(migrations, &gormigrate.Migration{ID: f.version, Migrate: f.apply})
	}
	return migrations, nil
}

// splitStatements splits an Atlas migration file into statements.
// Atlas writes full-line `--` comments and terminates every statement with `;` at the end of a line.
func splitStatements(content string) []string {
	var stmts []string
	var current strings.Builder
	for _, line := range strings.Split(content, "\n") {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "--") {
			continue
		}
		current.WriteString(line)
		current.WriteString("\n")
		if strings.HasSuffix(trimmed, ";") {
			stmts = append(stmts, strings.TrimSuffix(strings.TrimSpace(current.String()), ";"))
			current.Reset()
		}
	}
	if rest := strings.TrimSpace(current.String()); rest != "" {
		stmts = append(stmts, rest)
	}
	return stmts
}
